try {
  return [{ json: JSON.parse(cleanText) }];
} catch (e) {
  console.log('Parse error:', e);
  return [{ json: { risks: [], diet_plan: [], exercise_plan: [] } }];
}

// Get medical data from the parsing branch
const medicalData = $("parse medical data").first().json;

// Get recommendations from current branch
const recommendations = $json;

return [{
  json: {
    status: "success",
    structured_data: {
      hemoglobin: medicalData.hemoglobin || 'N/A',
      blood_sugar: medicalData.blood_sugar || 'N/A',
      cholesterol: medicalData.cholesterol || 'N/A'
    },
    raw_text: medicalData.summary || 'No summary available',
    risks: recommendations.risks || [],
    diet_plan: recommendations.diet_plan || [],
    exercise_plan: recommendations.exercise_plan || []
  }
}];
